*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:           #f4f5f7;
  --clr-surface:      #ffffff;
  --clr-border:       #d0d5dd;
  --clr-border-focus: #4f46e5;
  --clr-accent:       #4f46e5;
  --clr-accent-dark:  #4338ca;
  --clr-text:         #111827;
  --clr-text-muted:   #6b7280;
  --clr-error:        #b91c1c;
  --clr-error-bg:     #fef2f2;
  --clr-error-border: #fca5a5;
  --clr-success:      #065f46;
  --clr-success-bg:   #ecfdf5;
  --clr-success-border:#6ee7b7;
  --radius:           12px;
  --shadow:           0 4px 24px rgba(0,0,0,.08), 0 1px 4px rgba(0,0,0,.04);
  --transition:       150ms ease;
  font-size: 16px;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--clr-bg);
  color: var(--clr-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  line-height: 1.5;
}

/* ─── Skip link ─────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--clr-accent);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
  font-weight: 600;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ─── Card ──────────────────────────────────────────────── */
.card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 440px;
}

/* ─── Header ────────────────────────────────────────────── */
.card__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: #eef2ff;
  border-radius: 10px;
  margin-bottom: 1.25rem;
}
.card__icon svg { color: var(--clr-accent); }

.card__title {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -.015em;
  color: var(--clr-text);
  margin-bottom: .375rem;
}

.card__subtitle {
  font-size: .9375rem;
  color: var(--clr-text-muted);
  margin-bottom: 2rem;
}

/* ─── Form ──────────────────────────────────────────────── */
.consent-form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ─── form-field ────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

/* checkbox row */
.form-field__checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: .75rem;
}

/* custom checkbox */
.form-field__checkbox-row input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: .125rem;           /* optical alignment with label text */
  border: 2px solid var(--clr-border);
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  position: relative;
}

.form-field__checkbox-row input[type="checkbox"]:checked {
  background: var(--clr-accent);
  border-color: var(--clr-accent);
}

/* checkmark via pseudo-element */
.form-field__checkbox-row input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  top: 1px; left: 4px;
  width: 5px; height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.form-field__checkbox-row input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--clr-border-focus);
  outline-offset: 2px;
  border-color: var(--clr-border-focus);
}

