.form-field__label {
  font-size: .9375rem;
  color: var(--clr-text);
  cursor: pointer;
  line-height: 1.45;
  user-select: none;
}

.form-field__label a {
  color: var(--clr-accent);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.form-field__label a:hover { color: var(--clr-accent-dark); }
.form-field__label a:focus-visible {
  outline: 2px solid var(--clr-border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* required asterisk */
.required-mark {
  color: var(--clr-error);
  margin-inline-start: .15em;
  font-weight: 700;
}

/* helper text */
.form-field__helper {
  font-size: .8125rem;
  color: var(--clr-text-muted);
  padding-inline-start: calc(1.125rem + .75rem); /* indent under checkbox */
}

/* error text */
.form-field__error {
  font-size: .8125rem;
  color: var(--clr-error);
  padding-inline-start: calc(1.125rem + .75rem);
