  align-items: center;
  gap: .3rem;
}
.form-field__error[hidden] { display: none; }

/* error banner on form */
.form-field--has-error .form-field__checkbox-row input[type="checkbox"] {
  border-color: var(--clr-error);
}

/* ─── Submit button ─────────────────────────────────────── */
.btn-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  width: 100%;
  padding: .75rem 1.25rem;
  background: var(--clr-accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn-submit:hover  { background: var(--clr-accent-dark); }
.btn-submit:active { background: #3730a3; }
.btn-submit:focus-visible {
  outline: 3px solid var(--clr-border-focus);
  outline-offset: 3px;
}

/* ─── Status / live region ──────────────────────────────── */
.status-message {
  border-radius: 8px;
  padding: .875rem 1rem;
  font-size: .9375rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: .5rem;
}
.status-message[hidden] { display: none; }
.status-message--success {
  background: var(--clr-success-bg);
  border: 1px solid var(--clr-success-border);
  color: var(--clr-success);
}

/* ─── Reflow: single-column at narrow viewports ─────────── */
@media (max-width: 480px) {
  .card { padding: 1.75rem 1.25rem; }
}

/* ─── Forced colors (high-contrast) ────────────────────── */
@media (forced-colors: active) {
  .form-field__checkbox-row input[type="checkbox"] {
    forced-color-adjust: auto;
  }
  .btn-submit { forced-color-adjust: none; }
}

/* ─── Reduced motion ────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
