        <line x1="9" y1="17" x2="15" y2="17"/>
      </svg>
    </div>`;
}

function ConsentField() {
  return `
    <div class="form-field" id="consent-field">
      <div class="form-field__checkbox-row">
        <input
          id="agree-terms"
          type="checkbox"
          name="agree-terms"
          required
          aria-describedby="agree-helper agree-error"
        />
        <label for="agree-terms" class="form-field__label">
          I have read and agree to the
          <a href="/terms" target="_blank" rel="noopener noreferrer">Terms of Use</a>
          and
          <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.<span
            class="required-mark" aria-hidden="true">*</span>
        </label>
      </div>

      <p id="agree-helper" class="form-field__helper">
        You must accept the terms before your account can be created.
      </p>

      <p id="agree-error" class="form-field__error" hidden role="alert">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none"
             stroke="currentColor" stroke-width="2.5" stroke-linecap="round"
             stroke-linejoin="round" aria-hidden="true" focusable="false">
          <circle cx="12" cy="12" r="10"/>
          <line x1="12" y1="8" x2="12" y2="12"/>
          <line x1="12" y1="16" x2="12.01" y2="16"/>
        </svg>
        Error: You must agree to the Terms of Use to continue.
      </p>
    </div>`;
}

function SubmitButton() {
  return `
    <button type="submit" class="btn-submit">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none"
           stroke="currentColor" stroke-width="2.5" stroke-linecap="round"
           stroke-linejoin="round" aria-hidden="true" focusable="false">
        <polyline points="20 6 9 17 4 12"/>
      </svg>
      Agree and continue
    </button>`;
}

function StatusMessage() {
  return `
    <p id="form-status"
       class="status-message status-message--success"
       aria-live="polite"
       role="status"
       hidden>
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none"
           stroke="currentColor" stroke-width="2.5" stroke-linecap="round"
           stroke-linejoin="round" aria-hidden="true" focusable="false">
        <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/>
        <polyline points="22 4 12 15.01 9 12.01"/>
      </svg>
      You're all set! Your preferences have been saved.
    </p>`;
}

function ConsentForm() {
  return `
    <form
      id="consent-form"
      class="consent-form"
      novalidate
      aria-label="Terms of use agreement"
    >
      ${ConsentField()}
      ${StatusMessage()}
      ${SubmitButton()}
    </form>`;
}

function App() {
  return `
    <div class="card" role="region" aria-labelledby="card-title">
      ${CardIcon()}
      <h1 id="card-title" class="card__title">Terms of Use</h1>
      <p class="card__subtitle">
        Please review and accept our terms before getting started.
      </p>
      ${ConsentForm()}
    </div>`;
}

// ─── Mount ───────────────────────────────────────────────────────────────────

document.getElementById('root').innerHTML = App();

// ─── Event wiring ────────────────────────────────────────────────────────────

const form      = document.getElementById('consent-form');
const checkbox  = document.getElementById('agree-terms');
const errorMsg  = document.getElementById('agree-error');
const statusMsg = document.getElementById('form-status');
const field     = document.getElementById('consent-field');

/** Show or clear the validation error on the checkbox. */
function setCheckboxError(hasError) {
  if (hasError) {
    checkbox.setAttribute('aria-invalid', 'true');
    errorMsg.hidden = false;
    field.classList.add('form-field--has-error');
  } else {
    checkbox.removeAttribute('aria-invalid');
    errorMsg.hidden = true;
    field.classList.remove('form-field--has-error');
  }
}

// Clear error as soon as the user checks the box (live feedback).
checkbox.addEventListener('change', () => {
  if (checkbox.checked) setCheckboxError(false);
});

form.addEventListener('submit', (event) => {
  event.preventDefault();

  if (!checkbox.checked) {
    setCheckboxError(true);
    // Move focus to the checkbox so AT announces the associated error.
    checkbox.focus();
    return;
  }

  // Valid submission.
  setCheckboxError(false);
  statusMsg.hidden = false;

  // Disable form controls after successful submission.
  checkbox.disabled = true;
  form.querySelector('.btn-submit').disabled = true;
  form.querySelector('.btn-submit').textContent = 'Accepted';
});
