+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  padding: 2.5rem 2rem;
+  width: 100%;
+  max-width: 440px;
+}
+
+/* ─── Header ────────────────────────────────────────────── */
+.card__icon {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 48px;
+  height: 48px;
+  background: #eef2ff;
+  border-radius: 10px;
+  margin-bottom: 1.25rem;
+}
+.card__icon svg { color: var(--clr-accent); }
+
+.card__title {
+  font-size: 1.375rem;
+  font-weight: 700;
+  letter-spacing: -.015em;
+  color: var(--clr-text);
+  margin-bottom: .375rem;
+}
+
+.card__subtitle {
+  font-size: .9375rem;
+  color: var(--clr-text-muted);
+  margin-bottom: 2rem;
+}
+
+/* ─── Form ──────────────────────────────────────────────── */
+.consent-form { display: flex; flex-direction: column; gap: 1.5rem; }
+
+/* ─── form-field ────────────────────────────────────────── */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+
+/* checkbox row */
+.form-field__checkbox-row {
+  display: flex;
+  align-items: flex-start;
+  gap: .75rem;
+}
+
+/* custom checkbox */
+.form-field__checkbox-row input[type="checkbox"] {
+  appearance: none;
+  -webkit-appearance: none;
+  flex-shrink: 0;
+  width: 1.125rem;
+  height: 1.125rem;
+  margin-top: .125rem;
+  border: 2px solid var(--clr-border);
+  border-radius: 4px;
+  background: #fff;
+  cursor: pointer;
+  transition: border-color var(--transition), background var(--transition);
+  position: relative;
+}
+
+.form-field__checkbox-row input[type="checkbox"]:checked {
+  background: var(--clr-accent);
+  border-color: var(--clr-accent);
+}
+
+/* checkmark via pseudo-element */
+.form-field__checkbox-row input[type="checkbox"]:checked::after {
+  content: "";
+  position: absolute;
+  top: 1px; left: 4px;
+  width: 5px; height: 9px;
+  border: 2px solid #fff;
+  border-top: none;
+  border-left: none;
+  transform: rotate(45deg);
+}
+
+.form-field__checkbox-row input[type="checkbox"]:focus-visible {
+  outline: 3px solid var(--clr-border-focus);
+  outline-offset: 2px;
+  border-color: var(--clr-border-focus);
+}
+
+/* invalid state */
+.form-field__checkbox-row input[type="checkbox"][aria-invalid="true"] {
+  border-color: var(--clr-error);
+}
+
+/* label */
+.form-field__label {
+  font-size: .9375rem;
+  color: var(--clr-text);
+  cursor: pointer;
+  line-height: 1.45;
+  user-select: none;
+}
+
+.form-field__label a {
+  color: var(--clr-accent);
+  font-weight: 500;
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+.form-field__label a:hover { color: var(--clr-accent-dark); }
+.form-field__label a:focus-visible {
+  outline: 2px solid var(--clr-border-focus);
+  outline-offset: 2px;
+  border-radius: 2px;
+}
+
+/* required asterisk */
+.required-mark {
+  color: var(--clr-error);
+  margin-inline-start: .15em;
+  font-weight: 700;
+}
+
+/* helper text */
+.form-field__helper {
+  font-size: .8125rem;
+  color: var(--clr-text-muted);
+  padding-inline-start: calc(1.125rem + .75rem);
+}
+
+/* error text */
+.form-field__error {
+  font-size: .8125rem;
+  color: var(--clr-error);
+  padding-inline-start: calc(1.125rem + .75rem);
+  display: flex;
+  align-items: center;
+  gap: .3rem;
+}
+.form-field__error[hidden] { display: none; }
+
+/* error state on checkbox */
+.form-field--has-error .form-field__checkbox-row input[type="checkbox"] {
+  border-color: var(--clr-error);
+}
+
+/* ─── Submit button ─────────────────────────────────────── */
+.btn-submit {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .5rem;
+  width: 100%;
+  padding: .75rem 1.25rem;
+  background: var(--clr-accent);
+  color: #fff;
+  border: none;
+  border-radius: 8px;
+  font-size: 1rem;
+  font-weight: 600;
+  cursor: pointer;
+  transition: background var(--transition);
+}
+.btn-submit:hover  { background: var(--clr-accent-dark); }
+.btn-submit:active { background: #3730a3; }
+.btn-submit:focus-visible {
+  outline: 3px solid var(--clr-border-focus);
+  outline-offset: 3px;
+}
+
+/* ─── Status / live region ──────────────────────────────── */
+.status-message {
+  border-radius: 8px;
+  padding: .875rem 1rem;
+  font-size: .9375rem;
+  font-weight: 500;
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+}
+.status-message[hidden] { display: none; }
+.status-message--success {
+  background: var(--clr-success-bg);
+  border: 1px solid var(--clr-success-border);
+  color: var(--clr-success);
+}
+
+/* ─── Reflow ────────────────────────────────────────────── */
+@media (max-width: 480px) {
+  .card { padding: 1.75rem 1.25rem; }
+}
+
+/* ─── Forced colors (high-contrast) ────────────────────── */
+@media (forced-colors: active) {
+  .form-field__checkbox-row input[type="checkbox"] {
+    forced-color-adjust: auto;
+  }
+  .btn-submit { forced-color-adjust: none; }
+}
+
+/* ─── Reduced motion ────────────────────────────────────── */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { transition: none !important; }
+}
